const sd = $getWorkflowStaticData('global');
sd.seenMids = sd.seenMids || [];
sd.rate = sd.rate || {};

const out = [];
const now = Date.now();

for (const item of $input.all()) {
  const m = item.json.body?.entry?.[0]?.messaging?.[0];
  const mid = m?.message?.mid;
  const sender = m?.sender?.id;
  const isEcho = m?.message?.is_echo;

  if (mid) {
    if (sd.seenMids.includes(mid)) continue;
    sd.seenMids.push(mid);
    if (sd.seenMids.length > 300) sd.seenMids = sd.seenMids.slice(-300);
  }

  if (sender && !isEcho) {
    const hits = (sd.rate[sender] || []).filter(t => now - t < 60000);
    if (hits.length >= 12) continue;
    hits.push(now);
    sd.rate[sender] = hits;
  }

  out.push(item);
}

if (Object.keys(sd.rate).length > 500) sd.rate = {};

return out;

// نطلّع قيم الرسالة مرة وحدة حتى ما نكرر السلاسل الطويلة بكل عقدة
const wh = $json.body || $json;
const entry = wh.entry?.[0] || {};
const m = entry.messaging?.[0] || {};
const att = m.message?.attachments?.[0] || {};

return [{
  json: {
    senderId: m.sender?.id || '',
    mid: m.message?.mid || '',
    messageText: m.message?.text || '',
    attachmentType: att.type || '',
    attachmentUrl: att.payload?.url || ''
  }
}];

const item = $input.first();
let base64Audio = '';
let mimeType = 'audio/mp4';

// استخراج الملف بمرونة: جرّب المفتاح 'data' أولاً ثم أي مفتاح ثنائي متوفر
let buffer = null;
try {
  buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
} catch (e) {
  const bin = item.binary || {};
  const keys = Object.keys(bin);
  if (!keys.length) {
    buffer = null;
  } else {
    buffer = await this.helpers.getBinaryDataBuffer(0, keys[0]);
    if (bin[keys[0]]?.mimeType) mimeType = bin[keys[0]].mimeType;
  }
}

if (!buffer || buffer.length === 0) {
  throw new Error('فشل استخراج بيانات الصوت - الملف فارغ أو غير موجود');
}

// حد الإدخال المباشر (inline) عند Gemini تقريباً 20MB للطلب كامل
if (buffer.length > 18 * 1024 * 1024) {
  throw new Error('حجم الملف الصوتي كبير جداً: ' + buffer.length + ' بايت');
}

if (item.binary && item.binary.data) {
  const mt = item.binary.data.mimeType || '';
  if (mt.startsWith('audio/')) mimeType = mt;
}

base64Audio = buffer.toString('base64');
if (!base64Audio) {
  throw new Error('فشل استخراج بيانات الصوت - base64 فارغ');
}

return [{
  json: {
    reqBody: {
      contents: [{
        role: 'user',
        parts: [
          { inlineData: { mimeType: mimeType, data: base64Audio } },
          { text: 'فرّغ هذا التسجيل الصوتي إلى نص عربي بدقة. اكتب النص المنطوق فقط بدون أي تعليق أو مقدمة.' }
        ]
      }],
      generationConfig: { temperature: 0, maxOutputTokens: 2048 }
    }
  }
}];

const resp = $input.first().json || {};

let text = '';
try {
  const parts = resp.candidates?.[0]?.content?.parts || [];
  text = parts
    .filter(p => !p.thought && typeof p.text === 'string')
    .map(p => p.text)
    .join(' ')
    .trim();
} catch (e) {
  text = '';
}

const failed = !text;

return [{
  json: {
    transcribedText: failed
      ? '[ملاحظة نظام: المراجع دزّ بصمة صوتية لكن ما كدرنا نفرّغها. اعتذر منه بأدب واطلب منه يعيدها أو يكتب سؤاله نص.]'
      : text,
    transcriptionFailed: failed
  }
}];

const raw = $input.first().json.output;
const c = $('Combine Message').first().json;

let reply = '', name = '', phone = '', complete = false;

if (raw && typeof raw === 'object') {
  reply = String(raw.reply ?? '');
  name  = String(raw.name ?? '').trim();
  phone = String(raw.phone ?? '').trim();
  complete = raw.details_complete === true || raw.details_complete === 'true';
} else {
  // مسار احتياطي: إذا رجع النموذج نص خام لأي سبب
  let t = String(raw ?? '');
  const m = t.match(/\{[\s\S]*\}/);
  if (m) {
    try {
      const p = JSON.parse(m[0]);
      reply = String(p.reply ?? t.replace(m[0], ''));
      name  = String(p.name ?? '').trim();
      phone = String(p.phone ?? '').trim();
      complete = p.details_complete === true;
    } catch (e) {
      reply = t.replace(m[0], '');
    }
  } else {
    reply = t;
  }
}

// تنظيف: ما يوصل الزبون أي JSON أو code fence
reply = reply.replace(/```[a-z]*[\s\S]*?```/gi, '')
             .replace(/\{[\s\S]*"(name|phone|details_complete)"[\s\S]*\}/g, '');

// تحويل رموز السطر الحرفية (\n و \r) إلى أسطر فعلية
reply = reply.replace(/\\r\\n/g, '\n').replace(/\\n/g, '\n').replace(/\\r/g, '\n');

// إزالة كل الإيموجي والرموز التعبيرية نهائياً
reply = reply.replace(/[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{2190}-\u{21FF}\u{2B00}-\u{2BFF}\u{FE00}-\u{FE0F}\u{1F1E6}-\u{1F1FF}\u{200D}\u{2764}]/gu, '');

// تنظيف الفراغات الزائدة
reply = reply.replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim();
if (!reply) reply = 'تم استلام رسالتك، لحظة رجاءً.';

// التحقق من صحة الاسم والرقم قبل ما نحفظهم
const words = String(name).split(/\s+/).filter(Boolean);
const validName = words.length >= 2;
const phoneVal = String(phone).replace(/\s+/g, '');

// إذا الذكاء حذف الصفر الأول (مثل: كتب 7826040476 بدل 07826040476) أو كود الدولة نعيده
let fixedPhone = phoneVal;
const digits = phoneVal.replace(/\D/g, '');
if (digits.startsWith('964')) {
  fixedPhone = '0' + digits.slice(3);
} else if (digits.startsWith('00964')) {
  fixedPhone = '0' + digits.slice(5);
} else if (/^[1-9]\d{9,10}$/.test(digits)) {
  fixedPhone = '0' + digits;
} else if (digits.startsWith('0')) {
  fixedPhone = digits;
} else if (/^\d+$/.test(digits)) {
  fixedPhone = '0' + digits;
}

if (fixedPhone && !fixedPhone.startsWith('0') && !fixedPhone.startsWith('+')) {
  fixedPhone = '0' + fixedPhone;
}

const validPhone = /^0[1-9]\d{8,9}$/.test(fixedPhone) || /^\+?963\d{8,10}$/.test(fixedPhone);

const isAdmin = $('Check Admin & Routing').first().json.isAdmin === true;
const sd = $getWorkflowStaticData('global');
sd.savedPhones = sd.savedPhones || {};
sd.savedNames = sd.savedNames || {};

const currentPhone = validPhone ? fixedPhone : '';
const lastPhone = sd.savedPhones[c.senderId] || '';
const isNewOrUpdatedPhone = (currentPhone && currentPhone !== lastPhone);

const ready = validName && validPhone && !isAdmin && isNewOrUpdatedPhone;

if (ready) {
  sd.savedPhones[c.senderId] = fixedPhone;
  sd.savedNames[c.senderId] = name;
  sd.stats = sd.stats || { totalCustomers: 0, todayCustomers: 0, lastDate: '' };
  sd.stats.totalCustomers = (sd.stats.totalCustomers || 0) + 1;
  sd.stats.todayCustomers = (sd.stats.todayCustomers || 0) + 1;
}

return [{
  json: {
    senderId: c.senderId,
    adminSenderId: sd.adminSenderId || '',
    reply: reply,
    name: name,
    phone: ready ? fixedPhone : '',
    hasDetails: ready,
    messageToSend: reply
  }
}];

// نعرض فحصوى الخطأ الفعلي من العقدة اللي سلكت مسار الخطأ
const c = $('Combine Message').first().json;

// نجيب أول رسالة خطأ متاحة من دخل الـ error output
let detail = '';
for (const item of $input.all()) {
  const e = item.json?.error?.message
        || item.json?.error
        || item.json?.message
        || '';
  if (e) { detail = String(e); break; }
}
if (detail) detail = '\n(تفاصيل: ' + detail.slice(0, 250) + ')';

return [{
  json: {
    senderId: c.senderId,
    messageToSend: 'اعتذر، صار خلل تقني بسيط عندنا. رجاءً أعد إرسال رسالتك بعد لحظات.' + detail
  }
}];

const c = $('Combine Message').first().json;
return [{
  json: {
    senderId: c.senderId,
    messageToSend: 'اعتذر، ما أكدر أفتح هذا النوع من المرفقات. رجاءً اكتب سؤالك نص، أو دزّ صورة، أو بصمة صوتية.'
  }
}];
